    }
}

/// Greens for a leaf mass: deep shade, mid, light, full sun.
#[derive(Clone, Copy)]
struct Greens {
    shade: Rgb,
    mid: Rgb,
    light: Rgb,
    sun: Rgb,
}

impl Greens {
    fn at(&self, l: f32) -> Rgb {
        if l < 0.35 {
            mixc(self.shade, self.mid, l / 0.35)
        } else if l < 0.72 {
            mixc(self.mid, self.light, (l - 0.35) / 0.37)
        } else {
            mixc(self.light, self.sun, (l - 0.72) / 0.28)
        }
    }
    /// The same greens seen through `air` (0 near .. 1 far): paler, bluer,
    /// less contrast.
    fn far(&self, air: f32) -> Greens {
        let veil = hex("#9eaab0");
        Greens { shade: mixc(self.shade, veil, air * 0.8), mid: mixc(self.mid, veil, air * 0.7), light: mixc(self.light, veil, air * 0.6), sun: mixc(self.sun, veil, air * 0.5) }
    }
}

/// A small field tree or bush in the middle distance: a trunk stroke and
/// the leaf touches of a grown crown, in greens thinned by the air.
fn field_tree(c: &mut Canvas, pal: &Palette, crown: &[(f32, f32)], foot: (f32, f32), sp: &Species, g: &Greens, seed: u64, rng: &mut Rng) {
    let top = crown.iter().map(|p| p.1).fold(f32::MAX, f32::min);
    let bot = crown.iter().map(|p| p.1).fold(f32::MIN, f32::max);
    let trunk = vec![foot, (foot.0, bot - (bot - top) * 0.25)];
    let t = Tree::grow(crown, Some(&trunk), sp, &Season::named("summer").unwrap(), SUN, seed);
    let tw = ((bot - top) * 0.05).max(0.6);
    let mut b = Held::new(Tool::round_sable(tw), rng.next_u64());
    b.load(pal.paint(mixc(hex("#2c2a22"), g.shade, 0.5), 0.2), 0.8);
    c.drag(&mut b, &Gesture::new(vec![foot, (foot.0 + 0.2, bot - 1.0)]).pressure(0.9, 0.7).ramps(0.0, 0.2).orient(Orient::Across), None);
    let w = t.touch_w.max(0.55);
    let mut hd = Held::new(Tool { point: 0.7, ..Tool::round_sable(w) }, rng.next_u64());
    for tc in &t.touches {
        let l = (tc.lit + rng.normal() * 0.1).clamp(0.0, 1.0);
        hd.reload(pal.paint(g.at(l), 0.25), 0.6);
        c.drag(&mut hd, &Gesture::new(tc.pts.to_vec()).pressure(0.85, 0.2).ramps(0.05, 0.6).orient(Orient::Across), None);
    }
}

/// A rounded crown outline around (cx, cy): half-width rw, half-height rh.
fn blob(cx: f32, cy: f32, rw: f32, rh: f32, rng: &mut Rng) -> Vec<(f32, f32)> {
    let n = 14;
    (0..n).map(|i| {
        let a = i as f32 / n as f32 * std::f32::consts::TAU;
        let r = 1.0 + 0.1 * rng.normal();
        let flat = if a.sin() > 0.0 { 0.75 } else { 1.0 };
        (cx + a.cos() * rw * r, cy + a.sin() * rh * r * flat)
    }).collect()
}

